BEGIN;


ON CONFLICT (workspace_id,slug) DO UPDATE SET name=EXCLUDED.name,enabled=true;

ON CONFLICT (id) DO UPDATE SET status=EXCLUDED.status,last_health_at=now();

ON CONFLICT (id) DO UPDATE SET display_name=EXCLUDED.display_name,custom_fields=EXCLUDED.custom_fields,updated_at=EXCLUDED.updated_at;

ON CONFLICT (workspace_id,channel,external_user_id) DO UPDATE SET contact_id=EXCLUDED.contact_id;

ON CONFLICT (id) DO UPDATE SET control_mode=EXCLUDED.control_mode,unread_count=EXCLUDED.unread_count,last_message_at=EXCLUDED.last_message_at;

ON CONFLICT (workspace_id,event_id) DO NOTHING;

ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,color=EXCLUDED.color;

ON CONFLICT (id) DO UPDATE SET stage_id=EXCLUDED.stage_id,title=EXCLUDED.title,amount=EXCLUDED.amount;

ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name,status=EXCLUDED.status,channel_content=EXCLUDED.channel_content,audience_snapshot=EXCLUDED.audience_snapshot;

COMMIT;